// Events.
const (
	EventPress        EventKind = 1
	EventLongPress    EventKind = 2
	EventTextChanged  EventKind = 3
	EventSubmit       EventKind = 4
	EventFocus        EventKind = 5
	EventBlur         EventKind = 6
	EventToggled      EventKind = 7
	EventValueChanged EventKind = 8
	// EventScrolled: a Scroll's or List's content offset, in points from its content's top left, as it scrolls.
	EventScrolled EventKind = 9
	// EventEnvironment: sent for the root; the ID is the root's.
	EventEnvironment EventKind = 10
	// EventLifecycle: a Lifecycle value.
	EventLifecycle EventKind = 11
	// EventPopped: the user popped a Stack's top screen (its ID).
	EventPopped EventKind = 12
	// EventSelected: the user selected a tab or a segment (its index).
	EventSelected EventKind = 13
	// EventAction: a menu item, alert button or bar button (its index).
	EventAction    EventKind = 14
	EventDismissed EventKind = 15
	// EventRefresh: the user pulled to refresh.
	EventRefresh EventKind = 16
	EventPan     EventKind = 17
	EventPinch   EventKind = 18
	// EventRotate: two fingers turning: Rotation is the angle since they began.
	EventRotate EventKind = 19
	// EventSwipe: a SwipeDirection bit.
	EventSwipe EventKind = 20
	// EventLoaded: an image loaded: its natural size.
	EventLoaded EventKind = 21
	EventFailed EventKind = 22
	// EventNative: a native view's event: string name, u32 count, then named values as in Native's Prop.
	EventNative EventKind = 23
	// EventLink: a rich text's link was tapped (its URL).
	EventLink EventKind = 24
	// EventA11yAction: a screen reader took one of the view's A11yActions (its index).
	EventA11yAction EventKind = 25
	// EventAdjust: a screen reader adjusted the view: 1 up, -1 down.
	EventAdjust EventKind = 26
	// EventEnded: a Video played to its end.
	EventEnded EventKind = 27
	// EventNavigated: a WebView loaded a page (its URL).
	EventNavigated EventKind = 28
	// EventMessage: a WebView's page posted a message: window.asuka.postMessage(text).
	EventMessage EventKind = 29
	// EventIncomingURL: the app was opened with a URL (its scheme, or a universal or app link), at launch or since; to the root.
	EventIncomingURL EventKind = 30
	// EventFontLoaded: a font a FontFamily named by URL (under asuka dev) loaded, to the root: text in it is measured again.
	EventFontLoaded EventKind = 31
	// EventFrame: a frame the display draws (vsync), while Frames is on: its time in seconds (monotonic); to the root.
	EventFrame EventKind = 32
	// EventResult: a Call's answer, to the root: u32 call id, u8 ok, then the result's bytes (an error's message when not ok).
	EventResult EventKind = 33
	// EventColorChanged: the user chose a ColorPicker's color: a Color (RGBA).
	EventColorChanged EventKind = 34
	// EventWebState: a WebView's page changed: string URL, string title, u8 flags (1 loading, 2 can go back, 4 can go forward), f32 progress (0 to 1).
	EventWebState EventKind = 35
	// EventRequest: a WebView's page made a request (its URL), with Requests.
	EventRequest EventKind = 36
	// EventDownload: a WebView's page led to a file it can't show: string URL, string MIME type, string file name, i64 size (-1: unknown).
	EventDownload EventKind = 37
	// EventNewWindow: a WebView's page would open a page in a new window (its URL).
	EventNewWindow EventKind = 38
	// EventShared: another app shared with the app from its share sheet (iOS's share extension, Android's ACTION_SEND and ACTION_SEND_MULTIPLE, with asuka.json's shareTarget), at launch or since; to the root: u32 count, then per item u8 ShareKind, string text (a text, a link's URL), string path (a file: the app's copy), string name (the file's name where it came from), string MIME type, i64 size (-1: unknown).
	EventShared EventKind = 39
	// EventPressed: the view is pressed (true): a finger, or the mouse's primary button, went down on it (a moment later in a scrolling container, as the platform's own views are, so a scroll doesn't show it); or isn't any more (false): it lifted, moved off the view (back on, it's pressed again), or a scroll, another gesture, a long press or a drag took the touch. Listened for (or Hover), the host leaves off its own pressed and hover looks (Android's ripple, Windows' fills): the app draws them.
	EventPressed EventKind = 40
	// EventHover: a pointer (a mouse, a trackpad, an iPad's pointer, a hovering pencil or stylus) came over the view (true) or left it (false); it stays over while on the view's children, as CSS's :hover does.
	EventHover EventKind = 41
	// EventDragOver: a drag the view takes (DropAccept) came over it (Began), moved over it (Changed), or left it, ended or was dropped on it (Cancelled); X and Y are its place in the view.
	EventDragOver EventKind = 42
	// EventDrop: a drag the view takes was dropped on it: f32 x, y (its place in the view), u32 the view it was dragged from (0: another app's), u8 flags (1: its files are the app's own copies, in its caches), then its items as in Shared (none for a drag from the app: the core has them). Sent once the items are loaded and their files copied, which may be after DragOver's Cancelled.
	EventDrop EventKind = 43
	// EventSelectionChanged: a TextField's cursor or selection moved (the user's, or the text changing): u32 start, u32 end, in UTF-16 code units.
	EventSelectionChanged EventKind = 44
	// EventRichChanged: a Rich TextField's styled text changed (the user typed, or formatted it): as its Rich prop.
	EventRichChanged EventKind = 45
	// EventFormats: the styles where a Rich TextField's cursor is (what's typed next) or that all its selection has: u8 TextFormat bits (1 bold, 2 italic, 4 underline, 8 strikethrough, 16 monospaced), then the link (u32-length string; empty: none); as they change.
	EventFormats EventKind = 46
	// EventPasted: content of a TextField's PasteTypes was pasted or put in by the keyboard: its items as Shared's (files are the app's own copies, in its caches).
	EventPasted EventKind = 47
	// EventRowSelected: the user selected (true) or deselected (false) a selecting List's row; to its cell.
	EventRowSelected EventKind = 48
	// EventRowSelectBegin: the user began selecting rows at this one, the list not selecting: a two-finger pan over rows (iOS), a long press (Android); to its cell.
	EventRowSelectBegin EventKind = 49
	// EventRowInset: a List's rows' content is narrower than the core lays it out by X points at the leading edge and Y at the trailing (a selection control's room); to the list. The core lays its rows out again.
	EventRowInset EventKind = 50
	// EventDragging: the view's drag (DragItems): a DragPhase. Began as it lifts, then Dropped (a target took it, the app's or another app's) or Cancelled.
	EventDragging EventKind = 51
	// EventBack: the user went back from a Screen, Sheet or the root with InterceptBack, which the host didn't do.
	EventBack EventKind = 52
	// EventPaged: a Paging Scroll's swipe is settling on a page: its index from the content's physical start (left or top), page = offset / the scroll's size.
	EventPaged EventKind = 53
	// EventWindowState: a window's state changed (the user's doing or the app's), to its Window node or, for the main window, the root, while the core listens (and once as it starts listening): f32 x, y (its frame's top left on the screen, in points from the main display's; 0, 0 where the host can't tell, as on Wayland), f32 width, height (its content's size, in points), u8 WindowStateFlags bits (1 visible, 2 focused, 4 minimized, 8 maximized, 16 full screen, 32 always on top, 64 click-through).
	EventWindowState EventKind = 54
	// EventCloseRequest: the user asked to close a window (its close button, a shortcut, the taskbar's or Dock's menu) while the core listens for this on its Window node or, for the main window, the root: the window stays open, and the core closes it (a Window: Destroy; the main window: WindowAction Close) if the app lets it.
	EventCloseRequest EventKind = 55
	// EventKey: a key of the view's Keys went down, or repeated, while the keyboard's focus was in it: its index.
	EventKey EventKind = 56
)

