var eventPayloads = [...]Payload{0, PNone, PNone, PString, PNone, PNone, PNone, PBool, PFloat, PPoint, PEnvironment, PInt, PInt, PInt, PInt, PNone, PNone, PGesture, PGesture, PGesture, PInt, PPoint, PString, PBytes, PString, PInt, PInt, PNone, PString, PString, PString, PString, PFloat, PBytes, PInt, PBytes, PString, PBytes, PString, PBytes, PBool, PBool, PGesture, PBytes, PBytes, PBytes, PBytes, PBytes, PBool, PNone, PPoint, PInt, PNone, PInt, PBytes, PNone, PInt}

func (e EventKind) String() string {
	if int(e) < len(eventNames) && e > 0 {
		return eventNames[e]
	}
	return fmt.Sprintf("Event(%d)", e)
}

// EventPayload returns what events of kind e carry.
func EventPayload(e EventKind) Payload {
	if int(e) < len(eventPayloads) {
		return eventPayloads[e]
	}
	return 255
}

// Commands.
const (
	CmdFocus CommandID = 1
	CmdBlur  CommandID = 2
	// CmdListUpdate: args: u32 count, then count i64 item IDs in order; then u32 section count (0, or the args ending there: one section, without a header), per section u32 the index of its first item and i64 its ID (stable, as an item's). Sections are in order; the first starts at 0.
	CmdListUpdate CommandID = 3
	// CmdPresent: show a Sheet or Alert.
	CmdPresent CommandID = 4
	// CmdHaptic: args: u8 Haptic; sent to the root.
	CmdHaptic CommandID = 5
	// CmdAnimateBegin: args: f32 duration (seconds), u8 AnimationCurve, i32 repeat (times more; -1: forever), u8 autoreverses, f32 delay (seconds), f32 a spring's damping ratio (1: no overshoot), f32 a spring's initial velocity (the change's fraction per second); sent to the root: the frames and visual props up to AnimateEnd animate. A repeating animation stops when its prop is set again.
	CmdAnimateBegin CommandID = 6
	CmdAnimateEnd   CommandID = 7
	// CmdOpenURL: args: the URL; sent to the root: the system opens it (a browser, another app).
	CmdOpenURL CommandID = 8
	// CmdCall: args: u32 call id, string module, string method, then the call's bytes; sent to the root: the host runs the module's method (its own, or one an app registers) and answers with Result.
	CmdCall CommandID = 9
	// CmdCopy: args: the text; sent to the root: it's put on the clipboard.
	CmdCopy CommandID = 10
	// CmdPlay: sent to a Video.
	CmdPlay CommandID = 11
	// CmdPause: sent to a Video.
	CmdPause CommandID = 12
	// CmdSeek: args: f64 seconds from the start; sent to a Video.
	CmdSeek CommandID = 13
	// CmdEval: args: JavaScript; sent to a WebView: run in its page.
	CmdEval CommandID = 14
	// CmdFrames: args: u8 on; sent to the root: the host sends Frame at each vsync (CADisplayLink, Choreographer) while it's on.
	CmdFrames CommandID = 15
	// CmdAnnounce: args: the text; sent to the root: a screen reader, if one is on, reads it out.
	CmdAnnounce CommandID = 16
	// CmdShare: args: the text (a URL is shared as one); sent to the root: the system's share sheet.
	CmdShare CommandID = 17
	// CmdScrollTo: args: u32 item index, u8 animated; sent to a List: it scrolls the item into view.
	CmdScrollTo CommandID = 18
	// CmdScrollToOffset: args: f32 x, f32 y (points from the content's top left; clamped, so a large one is the end), u8 animated; sent to a Scroll or List.
	CmdScrollToOffset CommandID = 19
	// CmdAccent: args: u64 Color (0: the platform's), u8 flags (1: on Android, the wallpaper's colors where the system has them); sent to the root when it mounts: the app's accent color, which the platform's controls and Accent take (iOS: the tint color; Android: a Material 3 color scheme made from it).
	CmdAccent CommandID = 20
	// CmdWebNavigate: args: u8 0 back, 1 forward, 2 reload, 3 stop; sent to a WebView.
	CmdWebNavigate CommandID = 21
	// CmdMenuBar: args: the app's menus (desktop): u32 count, per menu a u32-length title and its items, a menu (ops/menu.go): u32 count, per item u8 flags (1 separator, 2 disabled, 4 checked, 8 destructive, 16 submenu), a u32-length title, a u32-length key (a character, or enter, escape, tab, space, delete, backspace, up, down, left, right, home, end, pageup, pagedown, f1-f12; empty: no shortcut), u8 modifiers (1 primary: ⌘ on macOS, Ctrl on Windows; 2 shift; 4 alt, a Mac's option; 8 control) and u8 MenuRole (1 quit: the host quits the app; 2 close: the host closes the window in use, as its close button does; 3 open recent: a Mac's host puts its own Open Recent submenu there, the others the item's submenu), then with flag 16 its submenu, a menu; sent to the root, again when they change: the host shows them with its own (a Mac's app, Edit and Window menus), and reports a chosen item, or its shortcut, with Action on the root carrying the item's index among all the menus' items, depth first (a submenu's items after the item that opens it; separators and submenus count).
	CmdMenuBar CommandID = 22
	// CmdWindowOptions: args: the main window's options (ops.WindowConfig, ops.AppendWindowConfig): f32 width, height, min width, min height, max width, max height (its content's, in points; 0: the host's, or no most), f32 x, y (its frame's top left on the screen, points from the main display's; with WindowPositioned), u32 WindowFlags (1 not resizable, 2 no minimize, 4 no maximize, 8 no close, 16 always on top, 32 hidden, 64 skip the taskbar, 128 centered, 256 positioned, 512 transparent, 1024 maximized, 2048 full screen, 4096 child of its parent, 8192 modal to its parent, 16384 a panel: floating, non-activating, on every Space, 32768 a flyout: frameless, hanging from its Flyout prop's anchor, closed as it loses the keyboard, 65536 sized to its content: WindowAction Fit sizes it, 131072 click-through: the mouse goes to what's behind it, 262144 shows the app's menu bar as the main window does: Windows' menu bar, Linux's main menu), u8 TitleBar, u64 background Color (0: the platform's), u32 parent (a Window's: the Window node or root it belongs to; 0: none), u32-length state key (where the host remembers its place; empty: not remembered, but the main window's is "main" then), then the title (rest of the args; empty: the app's name); sent to the root when it mounts.
	CmdWindowOptions CommandID = 23
	// CmdWindowTitle: args: the title (empty: the app's name); sent to the root when the main window's changes (desktop; mobile hosts have none).
	CmdWindowTitle CommandID = 24
	// CmdColorScheme: args: u8 ColorScheme; sent to the root: the app shows light or dark whatever the system's setting, or follows it again (iOS: the windows' overrideUserInterfaceStyle; Android: AppCompat's night mode).
	CmdColorScheme CommandID = 25
	// CmdLocale: args: u8 flags (1: right to left), then the BCP 47 tag of the language the app shows; sent to the root as it mounts (before any view is made, after Accent) and when it changes. The host mirrors what it draws itself (navigation, transitions, a list's swipes), its views' natural text alignment, and its own words in that language where the platform lets it.
	CmdLocale CommandID = 26
	// CmdSaveLocale: args: the BCP 47 tag of the language the app chose (ui.SetLocale), empty to follow the user's languages again; sent to the root. The host keeps it across launches where the system does (iOS's and macOS's AppleLanguages of the app's defaults, which Settings shows; Android 13's LocaleManager) or itself (Android before 13, Windows), and from then on reports it first in the environment's Languages.
	CmdSaveLocale CommandID = 27
	// CmdFormat: args: u8 TextFormat bits (as Formats'), u8 0 off, 1 on, 2 toggle (on unless all the selection has them); sent to a Rich TextField: the selection takes the styles, or, at the cursor, what's typed next. Reported with RichChanged and Formats.
	CmdFormat CommandID = 28
	// CmdSetLink: args: the URL (empty: none); sent to a Rich TextField: its selection links there (at the cursor, the link around it). Reported with RichChanged and Formats.
	CmdSetLink CommandID = 29
	// CmdInsertText: args: the text; sent to a TextField: it replaces the selection (or goes in at the cursor) as if typed, undoably, and is reported with TextChanged and SelectionChanged.
	CmdInsertText CommandID = 30
	// CmdShareClose: args: u8 how (0 done, 1 cancelled, 2 open the app with what was shared); sent to a share sheet's root (app.ShareSheet): it closes.
	CmdShareClose CommandID = 31
	// CmdA11yFocus: sent to a view: a screen reader, if one is on, moves its focus there (UIAccessibility's screenChanged with the view; Android's ACTION_ACCESSIBILITY_FOCUS).
	CmdA11yFocus CommandID = 32
	// CmdBackExit: sent to the root: the app's OnBack handlers let the user's back go on from the root, so the host does what the system would have (Android's back: the activity finishes or goes to the background).
	CmdBackExit CommandID = 33
	// CmdReplace: sent to a Stack: its screens destroyed after it, and the screen inserted next (its new first), change at once, with no pop or push: a SplitView's destination changing.
	CmdReplace CommandID = 34
	// CmdWindowAction: args: u8 WindowAction, then for Size and Fit f32 width, height (its content's, points; Fit: what its content measures, for a window sized to it, which a flyout is placed again at and a panel grows down from its top at) and for Position f32 x, y (its frame's top left, points from the main display's top left); sent to a Window node or, for the main window, the root (desktop and the web; mobile hosts have none).
	CmdWindowAction CommandID = 35
)

